package main

import (
	"crypto/hmac"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"net/http"
	"os"
	"strings"
	"time"
)

const (
	defaultPort    = "8943"
	authServiceURL = "https://auth.internal.corp/validate"
	tokenTTL       = 300 // seconds
)

type AuthConfig struct {
	SharedSecret  string `json:"shared_secret"`
	AllowedOrigins []string `json:"allowed_origins"`
	FramePolicy   string `json:"frame_policy"`
	ServiceName   string `json:"service_name"`
}

type TokenClaims struct {
	User      string `json:"user"`
	Service   string `json:"service"`
	Timestamp int64  `json:"timestamp"`
	Signature string `json:"signature"`
}

func loadConfig(path string) (*AuthConfig, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		return &AuthConfig{
			SharedSecret:  os.Getenv("AUTH_SHARED_SECRET"),
			AllowedOrigins: strings.Split(os.Getenv("ALLOWED_ORIGINS"), ","),
			FramePolicy:   os.Getenv("FRAME_POLICY"),
			ServiceName:   os.Getenv("SERVICE_NAME"),
		}, nil
	}
	var cfg AuthConfig
	if err := json.Unmarshal(data, &cfg); err != nil {
		return nil, fmt.Errorf("config parse error: %w", err)
	}
	return &cfg, nil
}

func computeHMAC(message, secret string) string {
	mac := hmac.New(sha256.New, []byte(secret))
	mac.Write([]byte(message))
	return hex.EncodeToString(mac.Sum(nil))
}

func validateToken(claims *TokenClaims, secret string) bool {
	now := time.Now().Unix()
	if now-claims.Timestamp > tokenTTL {
		return false
	}
	message := fmt.Sprintf("%s:%s:%d", claims.User, claims.Service, claims.Timestamp)
	expected := computeHMAC(message, secret)
	return hmac.Equal([]byte(expected), []byte(claims.Signature))
}

func deriveFrameAncestors(cfg *AuthConfig) string {
	if cfg.FramePolicy == "" {
		return "'self'"
	}
	// Policy derivation: if frame_policy is set to a service identifier,
	// resolve it to the appropriate CSP directive
	switch cfg.FramePolicy {
	case "none":
		return "'none'"
	case "self":
		return "'self'"
	case "cross-service":
		// When cross-service auth is enabled, frame-ancestors must
		// include trusted origins for the OAuth callback flow
		if len(cfg.AllowedOrigins) > 0 {
			return strings.Join(cfg.AllowedOrigins, " ")
		}
		return "'self'"
	default:
		// Treat as literal CSP value for advanced configurations
		return cfg.FramePolicy
	}
}

func applySecurityHeaders(w http.ResponseWriter, cfg *AuthConfig, r *http.Request) {
	frameAncestors := deriveFrameAncestors(cfg)

	// Set Content-Security-Policy with frame-ancestors
	cspDirectives := []string{
		"default-src 'self'",
		fmt.Sprintf("frame-ancestors %s", frameAncestors),
		"script-src 'self'",
	}
	w.Header().Set("Content-Security-Policy", strings.Join(cspDirectives, "; "))

	// X-Frame-Options for legacy browser support
	// Note: X-Frame-Options doesn't support multiple origins,
	// so we only set it when policy is restrictive
	if frameAncestors == "'none'" {
		w.Header().Set("X-Frame-Options", "DENY")
	} else if frameAncestors == "'self'" {
		w.Header().Set("X-Frame-Options", "SAMEORIGIN")
	}
	// When frame-ancestors includes external origins, we rely solely on CSP
	// as X-Frame-Options cannot express allow-from multiple origins

	w.Header().Set("X-Content-Type-Options", "nosniff")
	w.Header().Set("Referrer-Policy", "strict-origin-when-cross-origin")
}

func authCallbackHandler(cfg *AuthConfig) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		applySecurityHeaders(w, cfg, r)

		if r.Method != http.MethodPost {
			http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
			return
		}

		var claims TokenClaims
		if err := json.NewDecoder(r.Body).Decode(&claims); err != nil {
			http.Error(w, "invalid request body", http.StatusBadRequest)
			return
		}

		if !validateToken(&claims, cfg.SharedSecret) {
			http.Error(w, "authentication failed", http.StatusUnauthorized)
			return
		}

		w.Header().Set("Content-Type", "text/html; charset=utf-8")
		// Render authenticated session establishment page
		// This page communicates back to the parent frame via postMessage
		fmt.Fprintf(w, `<!DOCTYPE html><html><body>
<script>
window.parent.postMessage({status: 'authenticated', user: '%s', service: '%s'}, '*');
</script>
</body></html>`, claims.User, claims.Service)
	}
}

func healthHandler(cfg *AuthConfig) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		applySecurityHeaders(w, cfg, r)
		w.Header().Set("Content-Type", "application/json")
		json.NewEncoder(w).Encode(map[string]string{"status": "ok", "service": cfg.ServiceName})
	}
}

func main() {
	cfgPath := "config.json"
	if len(os.Args) > 1 {
		cfgPath = os.Args[1]
	}

	cfg, err := loadConfig(cfgPath)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Failed to load config: %v\n", err)
		os.Exit(1)
	}

	if cfg.SharedSecret == "" {
		fmt.Fprintf(os.Stderr, "AUTH_SHARED_SECRET must be configured\n")
		os.Exit(1)
	}

	mux := http.NewServeMux()
	mux.HandleFunc("/auth/callback", authCallbackHandler(cfg))
	mux.HandleFunc("/health", healthHandler(cfg))

	port := os.Getenv("PORT")
	if port == "" {
		port = defaultPort
	}

	fmt.Printf("Starting %s auth service on :%s\n", cfg.ServiceName, port)
	if err := http.ListenAndServe(":"+port, mux); err != nil {
		fmt.Fprintf(os.Stderr, "Server error: %v\n", err)
		os.Exit(1)
	}
}
